(function(){"use strict";var R=document.documentElement,t;var PAL=["#F07D70","#EAB354","#74C99F","#B690EA","#46BDB4","#74A2F0","#97A3B6"];function paleta(c){var m=(c||"").match(/\d+/g);if(!m||m.length<3)return"";var best="",dmin=1e9;PAL.forEach((function(h){var d=0;for(var i=0;i<3;i++){var x=parseInt(h.substr(1+2*i,2),16)-m[i];d+=x*x}if(d<dmin){dmin=d;best=h}}));return best}function run(){if(R.getAttribute("data-visual")!=="novo")return;var mapa={};document.querySelectorAll(".nav-item[title]").forEach((function(a){mapa[a.getAttribute("title").trim()]=(a.getAttribute("href")||"").replace(/^\//,"")}));var cards=document.querySelectorAll(".mod-card");cards.forEach((function(c){var h=c.querySelector("h3"),m=h&&mapa[h.textContent.trim()];if(m&&c.getAttribute("data-mod")!==m)c.setAttribute("data-mod",m)}));var g=document.querySelector(".grid-mods"),p=g&&g.previousElementSibling&&g.previousElementSibling.querySelector("p");if(p){var n=cards.length+" módulos";if(p.getAttribute("data-n")!==n)p.setAttribute("data-n",n)}document.querySelectorAll('div[style*="flex: 0 0 250px"]').forEach((function(col){var d=col.querySelector(":scope > div:first-child > span:first-child");if(!d)return;var cor=paleta(d.style.backgroundColor);if(cor&&col.style.getPropertyValue("--k")!==cor)col.style.setProperty("--k",cor)}))}new MutationObserver((function(){clearTimeout(t);t=setTimeout(run,120)})).observe(R,{childList:true,subtree:true});run();document.addEventListener("pointermove",(function(e){var c=e.target&&e.target.closest&&e.target.closest(".mod-card");if(!c)return;var r=c.getBoundingClientRect();c.style.setProperty("--mx",e.clientX-r.left+"px");c.style.setProperty("--my",e.clientY-r.top+"px")}),{passive:true})})();